CREATE OR REPLACE FUNCTION public.set_bank_import_guard_enforced(_enabled boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR public.is_super_admin() IS NOT TRUE THEN RAISE EXCEPTION 'Somente super admin pode ativar a proteção após publicação.'; END IF; IF _enabled IS NULL THEN RAISE EXCEPTION 'Informe o estado.'; END IF; INSERT INTO public.bank_import_guard_settings(singleton,enforced) VALUES(true,_enabled) ON CONFLICT(singleton) DO UPDATE SET enforced=excluded.enforced; RETURN _enabled; END $$;